import {isHypothesis} from './political-hypotheses.js';
import {renderQualitativePosition} from './figure-research-view.js';
import {AXES} from './context.js';
import {entityMedia} from './entity-media.js';
import {PERSON_DETAILS,renderPersonDetails} from './person-details.js';
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const known=value=>Number.isFinite(value)&&value>=0&&value<=100;
export const COMPARATOR_COLORS=['#035732','#2d4778','#a63d30'];
export function comparisonEntities(figures,parties){return [...figures.map(entity=>({id:'persona/'+entity.id,entity,party:false})),...parties.map(entity=>({id:'partido/'+entity.id,entity,party:true}))]}
export function compareEntities(first,second){
 const rows=AXES.map((axis,i)=>({axis,first:first.profile[i],second:second.profile[i],gap:known(first.profile[i])&&known(second.profile[i])?Math.abs(first.profile[i]-second.profile[i]):null}));
 const gaps=rows.map(x=>x.gap).filter(x=>x!==null),min=gaps.length?Math.min(...gaps):null,max=gaps.length?Math.max(...gaps):null;
 return rows.map(row=>({...row,similar:row.gap!==null&&row.gap===min,different:row.gap!==null&&max>min&&row.gap===max}));
}
const normalize=value=>String(value).normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLocaleLowerCase('es');
export function searchComparisonProfiles(choices,selected,query){const term=normalize(query.trim());return term?choices.filter(item=>!selected.includes(item.id)&&normalize([item.entity.name,item.entity.partyName,item.entity.short,PERSON_DETAILS[item.entity.id]?.party].join(' ')).includes(term)):[]}
export function selectedComparisonProfiles(choices,ids){return [...new Set(ids)].map(id=>choices.find(item=>item.id===id)).filter(Boolean).slice(0,3).map((item,index)=>({...item,color:COMPARATOR_COLORS[index],index}))}
export function comparisonShareHash(ids){return '#comparador/'+ids.slice(0,3).map(id=>encodeURIComponent(id.replace('/',':'))).join(',')}
export function comparisonIdsFromRoute(value=''){try{return value.split(',').map(id=>decodeURIComponent(id).replace(':','/'))}catch{return []}}
const type=item=>item.party?'Partido':'Personaje';
const media=item=>entityMedia(item.entity,{party:item.party});
const fiche=item=>'#'+(item.party?'partido':'ficha')+'/'+item.entity.id;
function position(axis,value){if(!known(value))return 'Sin puntaje';if(value===50)return '50% · Equilibrado';return `${Math.max(value,100-value)}% ${axis[value<50?'left':'right']}${Math.abs(value-50)<10?' · Equilibrado':''}`}
function legend(selected){return `<ul class="cmp-legend" aria-label="Perfiles y colores">${selected.map(item=>`<li style="--profile-color:${item.color}">${media(item)}<span>${esc(item.entity.name)}</span></li>`).join('')}</ul>`}
export function renderComparisonOptions(items){return items.map((item,index)=>`<li role="option" id="cmp-option-${index}" aria-selected="false"><button type="button" data-compare-add="${esc(item.id)}" tabindex="-1">${media(item)}<span><strong>${esc(item.entity.name)}</strong><small>${esc(item.party?item.entity.period:PERSON_DETAILS[item.entity.id]?.role||item.entity.era)}</small></span><em>${type(item)}</em></button></li>`).join('')}
function profilePanel(selected){return `<section class="cmp-panel cmp-profiles" id="cmp-profiles"><h2 tabindex="-1">Perfiles</h2>${selected.length?`<ul class="cmp-selected">${selected.map(item=>`<li class="cmp-profile compare-identity" style="--profile-color:${item.color}"><button type="button" class="cmp-remove" data-compare-remove="${esc(item.id)}" aria-label="Quitar a ${esc(item.entity.name)} de la comparación"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="m7 7 10 10M17 7 7 17"/></svg></button>${media(item)}<span class="cmp-type">${type(item)}</span><strong>${esc(item.entity.name)}</strong></li>`).join('')}</ul>`:''}${selected.length<3?`<div class="cmp-search"><label class="sr-only" for="compare-search">Buscar un perfil para comparar</label><input type="search" id="compare-search" role="combobox" aria-autocomplete="list" aria-expanded="false" aria-controls="compare-options" autocomplete="off" placeholder="Buscá un político o partido"><ul role="listbox" aria-label="Perfiles encontrados" id="compare-options" hidden></ul><p class="cmp-search-empty" id="compare-empty" hidden>No encontramos ese perfil. Probá con otro nombre.</p></div>`:'<p class="cmp-limit">Hasta tres perfiles. Quitá uno para elegir otro.</p>'}${selected.length<2?`<p class="cmp-hint">${selected.length?'Elegí un perfil más para comparar.':'Elegí dos o tres perfiles para verlos lado a lado.'}</p>`:''}<p class="sr-only" role="status" id="compare-status"></p></section>`}
const poleColors=[['#3c6b8b','#a87a22'],['#16877d','#b88525'],['#3c7994','#8d649f'],['#987b2b','#965681'],['#2d7c74','#986244'],['#984e81','#765d44'],['#3c8185','#a46b39'],['#3f8293','#98703f'],['#507f72','#965966'],['#4c819e','#a16f3f'],['#616d9b','#a47c3d'],['#40885f','#b47b32']];
function axisTrack(axis,selected,{compact=false}={}){
 const available=selected.filter(item=>known(item.entity.profile[axis.id]));
 // Separate coincident labels vertically; their horizontal position remains the stored score.
 const lanes=[];const pins=available.map((item,trackIndex)=>{const value=item.entity.profile[axis.id];let row=lanes.findIndex(lane=>lane.every(other=>Math.abs(other-value)>=25));if(row<0){row=lanes.length;lanes.push([])}lanes[row].push(value);return `<span class="cmp-pin" style="left:${value}%;--profile-color:${item.color};--pin-row:${row};--profile-index:${trackIndex};--pin-align:${value<20?0:value>80?-100:-50}%" tabindex="0" aria-label="${esc(item.entity.name)}: ${esc(position(axis,value))}${isHypothesis(item.entity,axis.id)?' · hipótesis muy incierta':''}" data-tip="${esc(item.entity.name)} · ${esc(position(axis,value))}${isHypothesis(item.entity,axis.id)?' · hipótesis muy incierta':''}"><span class="cmp-pin-name">${esc(item.entity.name)}</span></span>`}).join('');
 return `<div class="cmp-track${available.length?'':' is-empty'}" role="img" aria-label="${esc(axis.name+': '+selected.map(item=>item.entity.name+' '+position(axis,item.entity.profile[axis.id])).join('; '))}" style="--pin-rows:${Math.max(0,lanes.length-1)};--profile-count:${Math.max(1,available.length)}"><span class="cmp-midpoint"></span>${pins}</div><div class="cmp-poles"><span>${esc(axis.left)}</span><span>${esc(axis.right)}</span></div>${compact?'':selected.map(item=>known(item.entity.profile[axis.id])?`<p class="cmp-axis-value" style="--profile-color:${item.color}"><span class="cmp-dot"></span><span>${esc(item.entity.name)}${isHypothesis(item.entity,axis.id)?'<br><small class="cmp-hypothesis">Hipótesis muy incierta</small>':''}</span><strong>${esc(position(axis,item.entity.profile[axis.id]))}</strong></p>`:`<div class="${item.entity.axisResearch?'compare-documentary':'cmp-missing'} compare-position"><span>${esc(item.entity.name)}</span>${renderQualitativePosition(item.entity,axis.id)||'<p class="compare-qualitative"><strong>Sin puntaje documentado</strong><span>Se conserva el dato desconocido.</span></p>'}</div>`).join('')}`;
}
function evidence(axis,selected){return `<details class="cmp-evidence"><summary>Fundamentos y fuentes</summary>${selected.map(item=>{const e=item.entity;return `<h4>${esc(e.name)}</h4><p>${esc(e.period||e.era)}</p><p>${esc(e.rationale[axis.id])}</p>${isHypothesis(e,axis.id)?'<p><strong>Contexto de la inferencia; no demuestra esta postura:</strong></p>'+e.placementResearch[axis.id].refs.map(ref=>{const source=e.sources[ref.source];return `<p><a href="${esc(ref.page?source.url.split('#')[0]+'#page='+ref.page:source.url)}" target="_blank" rel="noopener noreferrer">${esc(source.title)}</a></p>`}).join(''):''}${(e.evidence||[]).filter(ev=>ev.axis===axis.id).map(ev=>{const s=e.sources[ev.source];return s?`<p><a href="${esc(ev.page?s.url.split('#')[0]+'#page='+ev.page:s.url)}" target="_blank" rel="noopener noreferrer">${esc(s.title)}${ev.page?' · p. '+ev.page:''}</a></p>`:''}).join('')}`}).join('')}</details>`}
function axesPanel(selected){return `<section class="cmp-panel" id="cmp-axes"><h2>Los doce ejes</h2>${legend(selected)}<div class="cmp-axes">${AXES.map((axis,i)=>`<article class="compare-axis cmp-axis" data-axis="${i}" style="--pole-left:${poleColors[i][0]};--pole-right:${poleColors[i][1]}"><h3>${esc(axis.name)}</h3>${axisTrack(axis,selected)}${evidence(axis,selected)}</article>`).join('')}</div><p class="cmp-note">Las ubicaciones son editoriales. Las hipótesis se marcan como muy inciertas; sus referencias aportan contexto y no prueban la postura. Los ejes sin puntaje no se ubican en el centro.</p></section>`}
function ideologyPanel(selected){return `<section class="cmp-panel" id="cmp-ideologies"><h2>Corrientes políticas</h2><div class="cmp-ideologies">${selected.map(item=>`<article class="cmp-ideology" style="--profile-color:${item.color}"><div class="cmp-person-label">${media(item)}<span>${esc(item.entity.name)}</span></div><h3>${esc(item.party?item.entity.short:PERSON_DETAILS[item.entity.id]?.orientation||item.entity.orientation)}</h3>${item.party?`<p>${esc(item.entity.summary)}</p>`:renderPersonDetails(item.entity)}<p class="cmp-period">${esc(item.entity.period||item.entity.era)}</p><a href="${fiche(item)}">Ver ficha de ${esc(item.entity.name)} <span aria-hidden="true">→</span></a></article>`).join('')}</div></section>`}
function pairs(selected){return selected.flatMap((first,i)=>selected.slice(i+1).map(second=>({first,second,rows:compareEntities(first.entity,second.entity)})))}
function differencePanel(selected){return `<section class="cmp-panel" id="cmp-differences"><h2>Lo que los distingue</h2>${pairs(selected).map(({first,second,rows})=>{const common=rows.filter(row=>row.gap!==null),closest=common.find(row=>row.similar),farthest=[...common].sort((a,b)=>b.gap-a.gap)[0],opposite=common.filter(row=>(row.first-50)*(row.second-50)<0);return `<div class="cmp-pair"><h3>${esc(first.entity.name)} <span aria-hidden="true">×</span> ${esc(second.entity.name)}</h3>${common.length?`<div class="cmp-difference-grid">${[[farthest,'Donde más se diferencian'],[closest,'Donde más coinciden']].map(([row,label])=>`<article class="cmp-difference"><p>${label}</p><h4>${esc(row.axis.name)}</h4><strong class="cmp-gap-number">${row.gap}<small> puntos</small></strong>${axisTrack(row.axis,[first,second],{compact:true})}</article>`).join('')}</div><p class="cmp-opposites">Polos opuestos en <strong>${opposite.length} de ${common.length}</strong> ejes con puntajes comunes.${opposite.length?' '+opposite.map(row=>esc(row.axis.name)).join(' · ')+'.':''}</p>`:'<p class="cmp-note">Estas fichas no tienen puntajes comunes. Podés contrastar sus posiciones documentadas en los doce ejes.</p>'}<p class="compare-gap sr-only">${common.length?'Las diferencias se calculan solamente en ejes con puntajes comunes.':'Sin puntajes comunes para medir una diferencia en este eje.'}</p></div>`}).join('')}</section>`}
function compassPanel(selected){
 const available=selected.filter(item=>[0,3].every(i=>known(item.entity.profile[i]))),groups=new Map(),cells=[];
 for(const item of available){const key=item.entity.profile[0]+','+item.entity.profile[3];groups.set(key,[...(groups.get(key)||[]),item])}
 const mix=(a,b,t)=>a.map((n,i)=>Math.round(n+(b[i]-n)*t));
 for(let row=0;row<9;row++)for(let col=0;col<9;col++)cells.push(`<rect x="${55+col*31}" y="${45+row*31}" width="29" height="29" rx="2" fill="rgb(${mix(mix([224,104,128],[94,137,225],col/8),mix([97,198,157],[232,198,92],col/8),row/8).join(',')})"/>`);
 const marks=[...groups.values()].map(items=>{const f=items[0],x=55+f.entity.profile[0]*2.77,y=45+(100-f.entity.profile[3])*2.77;return `<g><title>${esc(items.map(item=>item.entity.name).join(' y '))}</title><circle cx="${x}" cy="${y}" r="${items.length>1?17:13}" fill="${items.length>1?'#26313d':f.color}" stroke="#fff" stroke-width="2"/><text x="${x}" y="${y+4}" fill="#fff" text-anchor="middle" font-size="11" font-weight="600">${items.map(item=>item.index+1).join('·')}</text></g>`}).join('');
 return `<section class="cmp-panel" id="cmp-compass"><h2>Brújula política</h2>${available.length?`<svg class="cmp-compass" viewBox="0 0 390 370" role="img" aria-label="Economía y seguridad de ${esc(available.map(item=>item.entity.name).join(', '))}. Los números identifican los perfiles de la leyenda."><text x="194" y="22" text-anchor="middle">Control y autoridad</text><text x="194" y="352" text-anchor="middle">Libertades individuales</text><text transform="translate(22 184) rotate(-90)" text-anchor="middle">Intervención estatal</text><text transform="translate(365 184) rotate(90)" text-anchor="middle">Libre mercado</text>${cells.join('')}<path d="M193.5 45V322M55 183.5H332" fill="none" stroke="#26313d" stroke-width="2"/>${marks}</svg><ol class="cmp-compass-legend">${available.map(item=>`<li style="--profile-color:${item.color}"><span>${item.index+1}</span>${media(item)}${esc(item.entity.name)}</li>`).join('')}</ol>`:'<p class="cmp-note">No hay coordenadas comparables para las fichas seleccionadas.</p>'}${selected.filter(item=>!available.includes(item)).map(item=>`<p class="cmp-note">${esc(item.entity.name)}: sin puntajes para ubicarlo en la brújula.</p>`).join('')}<p class="cmp-note">Proyección de economía y seguridad; no mide autoritarismo ni resume los doce ejes.</p></section>`;
}
const sections=[['cmp-ideologies','Corrientes'],['cmp-axes','Doce ejes'],['cmp-differences','Diferencias'],['cmp-compass','Brújula']];
export function renderComparator(choices,firstOrIds=[],secondId,thirdId){
 const ids=Array.isArray(firstOrIds)?firstOrIds:[firstOrIds,secondId,thirdId],selected=selectedComparisonProfiles(choices,ids),ready=selected.length>=2;
 return `<div class="cmp-top-actions">${ready?'<button type="button" class="cmp-share" data-compare-share>Compartir comparación <svg viewBox="0 0 24 24" aria-hidden="true"><path d="M12 16V3m-5 5 5-5 5 5M5 13v7h14v-7"/></svg></button>':''}</div><div class="cmp-layout"><div class="cmp-content">${profilePanel(selected)}${ready?ideologyPanel(selected)+axesPanel(selected)+differencePanel(selected)+compassPanel(selected):''}</div>${ready?`<aside class="cmp-side"><nav class="cmp-index results-index" aria-label="En esta página"><p>En esta página</p><a href="#cmp-profiles" data-jump="cmp-profiles">Perfiles</a>${sections.map(([id,label],i)=>`<a href="#${id}" data-jump="${id}"><span>${String(i+1).padStart(2,'0')}</span>${label}</a>`).join('')}</nav></aside>`:''}</div>`;
}
